F=out
def check(f, name):
    bad=[]
    for r in range(30):
        for c in range(30):
            rr,cc=f(r,c)
            if 0<=rr<30 and 0<=cc<30:
                if F[r][c]!=F[rr][cc]: bad.append((r,c,F[r][c],F[rr][cc]))
    print(name, len(bad), bad[:5])
